// Gera tests/fixtures/tres-mesas.gcode.3mf: projeto do Bambu Studio (A1 com AMS Lite) com 4 mesas,
// 3 fatiadas e 1 não fatiada, no mesmo formato de Metadata/slice_info.config e model_settings.config
// dos arquivos reais. Rodar com: node tests/fixtures/tres-mesas/gerar.mjs
//
// Mesa 1 "Base"      1h30 · slot 1 PLA laranja 40 g · slot 2 PLA branco 10 g
// Mesa 2 "Tampa"     45min · slot 1 PLA laranja 20 g · slot 3 PETG preto 15 g
// Mesa 3 "Detalhes"  30min · slot 2 PLA branco 5 g   · slot 4 PLA vermelho 8 g
// Mesa 4 "Rascunho"  não fatiada
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import JSZip from "jszip";

const filament = (id, type, color, grams) =>
  `    <filament id="${id}" tray_info_idx="GFA00" type="${type}" color="${color}" used_m="${(grams / 3).toFixed(2)}" used_g="${grams.toFixed(2)}" />`;

const plate = (index, seconds, objects, filaments) => `  <plate>
    <metadata key="index" value="${index}"/>
    <metadata key="printer_model_id" value="N2S"/>
    <metadata key="nozzle_diameters" value="0.4"/>
    <metadata key="prediction" value="${seconds}"/>
    <metadata key="weight" value="${filaments.reduce((s, f) => s + f[3], 0).toFixed(2)}"/>
    <metadata key="outside" value="false"/>
${objects.map((name, i) => `    <object identify_id="${index * 100 + i}" name="${name}" skipped="false" />`).join("\n")}
${filaments.map((f) => filament(...f)).join("\n")}
  </plate>`;

const sliceInfo = `<?xml version="1.0" encoding="UTF-8"?>
<config>
  <header>
    <header_item key="X-BBL-Client-Type" value="slicer"/>
    <header_item key="X-BBL-Client-Version" value="02.04.00.70"/>
  </header>
${plate(1, 5400, ["Base do porta-trecos"], [[1, "PLA", "#FF6600FF", 40], [2, "PLA", "#FFFFFFFF", 10]])}
${plate(2, 2700, ["Tampa"], [[1, "PLA", "#FF6600FF", 20], [3, "PETG", "#000000FF", 15]])}
${plate(3, 1800, ["Letras", "Puxador"], [[2, "PLA", "#FFFFFFFF", 5], [4, "PLA", "#FF0000FF", 8]])}
  <plate>
    <metadata key="index" value="4"/>
    <metadata key="prediction" value=""/>
    <metadata key="weight" value=""/>
  </plate>
</config>
`;

const modelPlate = (id, name) => `  <plate>
    <metadata key="plater_id" value="${id}"/>
    <metadata key="plater_name" value="${name}"/>
    <metadata key="locked" value="false"/>
    <metadata key="thumbnail_file" value="Metadata/plate_${id}.png"/>
  </plate>`;

const modelSettings = `<?xml version="1.0" encoding="UTF-8"?>
<config>
${modelPlate(1, "Base")}
${modelPlate(2, "Tampa")}
${modelPlate(3, "Detalhes")}
${modelPlate(4, "Rascunho")}
</config>
`;

const zip = new JSZip();
zip.file(
  "[Content_Types].xml",
  `<?xml version="1.0" encoding="UTF-8"?>\n<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/><Default Extension="gcode" ContentType="text/x.gcode"/></Types>\n`,
);
zip.file("3D/3dmodel.model", `<?xml version="1.0" encoding="UTF-8"?>\n<model unit="millimeter" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02"><resources/><build/></model>\n`);
zip.file("Metadata/slice_info.config", sliceInfo);
zip.file("Metadata/model_settings.config", modelSettings);
for (const i of [1, 2, 3]) zip.file(`Metadata/plate_${i}.gcode`, `; HEADER_BLOCK_START\n; generated by BambuStudio 02.04.00.70\n; HEADER_BLOCK_END\nG28\n`);

const out = fileURLToPath(new URL("../tres-mesas.gcode.3mf", import.meta.url));
writeFileSync(out, await zip.generateAsync({ type: "uint8array", compression: "DEFLATE" }));
console.log("gerado:", out);
